const $=s=>document.querySelector(s);const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initialMovies=[{title:'Sergam',genre:'Drama',runtime:132,status:'Now showing'},{title:'Hing',genre:'Romance',runtime:118,status:'Now showing'},{title:'The Monk and the Gun',genre:'Drama',runtime:107,status:'Now showing'}];let movies;try{movies=JSON.parse(localStorage.getItem('druk-movies'))||initialMovies}catch{movies=initialMovies}let page='overview';
const bookings=[['DC-1048','Pema Dorji','Sergam','2','600','Confirmed'],['DC-1047','Sonam Choden','Hing','3','900','Confirmed'],['DC-1046','Karma Wangchuk','The Monk and the Gun','2','600','Pending'],['DC-1045','Tshering Yangden','Sergam','4','1,200','Confirmed']];
function toast(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').style.display='none',3500)}
function table(rows){return `<table><thead><tr><th>Booking ID</th><th>Customer</th><th>Movie</th><th>Amount</th><th>Status</th></tr></thead><tbody>${rows.map(b=>`<tr><td>#${b[0]}</td><td><div class="customer"><span class="initials">${b[1].split(' ').map(x=>x[0]).slice(0,2).join('')}</span>${b[1]}</div></td><td>${b[2]}</td><td>Nu. ${b[4]}</td><td><span class="badge ${b[5]==='Pending'?'pending':''}">${b[5]}</span></td></tr>`).join('')}</tbody></table>`}
function renderStats(range='today'){const values={today:['24,600','82','3','78%'],week:['148,500','495','3','74%'],month:['592,800','1,976','3','81%']}[range];$('#stats').innerHTML=['Total revenue','Tickets booked','Movies showing','Seat occupancy'].map((label,i)=>`<article class="stat"><div class="stat-label">${label}<span class="stat-icon">${['↗','▤','▣','◉'][i]}</span></div><strong>${i===0?'Nu. ':''}${values[i]}</strong><small><b>↗ ${['12.8','8.2','2','5.4'][i]}${i===2?' new':'%'}</b> ${i===2?'this week':'vs. previous period'}</small></article>`).join('')}
function preview(){ $('#movie-preview').innerHTML=movies.filter(m=>m.status==='Now showing').slice(0,3).map((m,i)=>`<div class="movie-row"><div class="poster p${i}">${esc(m.title)}</div><div><h3>${esc(m.title)}</h3><p>${esc(m.genre)} · ${m.runtime} min</p></div><div class="rating">★ ${[4.8,4.7,4.9][i]}<small>Now showing</small></div></div>`).join('')||'<p class="empty">No movies showing.</p>'}
function navigate(next){page=next;location.hash=next;$('#overview').hidden=next!=='overview';$('#management').hidden=next==='overview';document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===next));$('#crumb').textContent=next[0].toUpperCase()+next.slice(1);$('#page-title').innerHTML=({overview:'Dashboard overview',movies:'Movie library',showtimes:'Showtime schedule',bookings:'Cinema bookings'}[next])+'<span>.</span>';$('#subtitle').textContent={overview:'Welcome back, Admin. Here’s what’s happening at Druk Cinema.',movies:'Manage the stories that bring your audience together.',showtimes:'Plan the day, one screening at a time.',bookings:'Keep track of every seat and every guest.'}[next];$('#sidebar').classList.remove('open');if(next==='movies')renderMovies();if(next==='bookings')renderBookings();if(next==='showtimes')renderShowtimes()}
function renderMovies(query=''){$('#management').innerHTML=`<div class="management-tools"><input id="movie-search" aria-label="Search movies" placeholder="Search movies…" value="${esc(query)}"><select id="movie-filter" aria-label="Filter movies"><option>All movies</option><option>Now showing</option><option>Coming soon</option></select></div><div class="movie-cards" id="movie-cards"></div>`;const update=()=>{$('#movie-cards').innerHTML=movies.map((m,i)=>({...m,index:i})).filter(m=>m.title.toLowerCase().includes($('#movie-search').value.toLowerCase())&&($('#movie-filter').value==='All movies'||m.status===$('#movie-filter').value)).map(m=>`<article class="panel movie-card"><div class="poster p${m.index%3}">${esc(m.title)}</div><span class="badge ${m.status==='Coming soon'?'pending':''}">${m.status}</span><h2 style="margin-top:16px">${esc(m.title)}</h2><p>${esc(m.genre)} · ${m.runtime} minutes</p><button data-toggle="${m.index}">${m.status==='Now showing'?'Move to coming soon':'Mark as now showing'}</button></article>`).join('')||'<p class="empty">No movies match your search.</p>';document.querySelectorAll('[data-toggle]').forEach(b=>b.onclick=()=>{const m=movies[Number(b.dataset.toggle)];m.status=m.status==='Now showing'?'Coming soon':'Now showing';saveMovies();update()})};$('#movie-search').oninput=update;$('#movie-filter').onchange=update;update()}
function renderBookings(){$('#management').innerHTML='<div class="management-tools"><input id="booking-search" aria-label="Search bookings" placeholder="Search by name, movie or booking ID…"><button id="booking-export">↓ Export bookings</button></div><article class="panel" id="bookings-list"></article>';const update=()=>{const q=$('#booking-search').value.toLowerCase();const rows=bookings.filter(b=>b.join(' ').toLowerCase().includes(q));$('#bookings-list').innerHTML=rows.length?table(rows):'<p class="empty">No bookings found.</p>'};$('#booking-search').oninput=update;$('#booking-export').onclick=()=>download('druk-bookings.csv','Booking ID,Customer,Movie,Tickets,Amount (Nu),Status\n'+bookings.map(b=>b.map(c=>'"'+c.replace(/"/g,'""')+'"').join(',')).join('\n'));update()}
function renderShowtimes(){$('#management').innerHTML=`<div class="management-tools"><span class="date">Monday, 19 October 2026</span></div><article class="panel">${movies.filter(m=>m.status==='Now showing').map((m,i)=>`<div class="showtime"><div><h2>${esc(m.title)}</h2><p>Main auditorium · ${m.runtime} min</p></div><span>${['10:00 AM','02:00 PM','06:00 PM'][i%3]}</span><span class="badge">Scheduled</span></div>`).join('')||'<p class="empty">Mark a movie as now showing to see its sample screening.</p>'}</article><p style="margin-top:16px">Sample screening schedule · Connect a booking service to manage live availability.</p>`}
function saveMovies(){localStorage.setItem('druk-movies',JSON.stringify(movies));preview()}
function download(name,content){const url=URL.createObjectURL(new Blob([content],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Report exported')}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));document.querySelectorAll('[data-goto]').forEach(b=>b.onclick=()=>navigate(b.dataset.goto));document.querySelectorAll('[data-range]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-range]').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');renderStats(b.dataset.range)});$('#menu').onclick=()=>$('#sidebar').classList.toggle('open');$('#add-movie').onclick=()=>$('#movie-dialog').showModal();$('#close-dialog').onclick=()=>$('#movie-dialog').close();$('#movie-form').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target);const title=f.get('title').trim();if(!title){toast('Enter a movie title');return}movies.push({title,genre:f.get('genre'),runtime:Number(f.get('runtime')),status:f.get('status')});saveMovies();$('#movie-dialog').close();e.target.reset();if(page==='movies')renderMovies();if(page==='showtimes')renderShowtimes();toast('Movie added to your library')};$('#notifications').onclick=()=>toast('You have 1 pending sample booking: DC-1046');$('#export').onclick=()=>download('druk-revenue-report.csv','Day,Revenue (Nu)\nMonday,12000\nTuesday,18500\nWednesday,14500\nThursday,22000\nFriday,28500\nSaturday,23000\nSunday,30000');window.addEventListener('hashchange',()=>{const p=location.hash.slice(1);if(['overview','movies','bookings','showtimes'].includes(p)&&p!==page)navigate(p)});renderStats();preview();$('#recent-table').innerHTML=table(bookings);navigate(['overview','movies','bookings','showtimes'].includes(location.hash.slice(1))?location.hash.slice(1):'overview');
